"use client";

import { useCallback, useEffect, useRef, useState } from "react";

/**
 * Minimal async data hook for the Superuser dashboard pages.
 *
 * Encapsulates the load / reload / error / cancelled-request dance that every
 * data-driven page needs, so a page body is just "call the hook, render the
 * state". Requests are keyed by `deps`; changing them discards the in-flight
 * response so a slow earlier request can never overwrite fresher data.
 */
export interface AsyncData<T> {
  data: T | null;
  isLoading: boolean;
  /** True only for the first load, so refreshes don't blank the page. */
  isInitialLoading: boolean;
  error: string | null;
  reload: () => void;
  setData: (updater: T | ((current: T | null) => T | null)) => void;
}

export interface UseAsyncDataOptions {
  /** Skip fetching entirely (e.g. while a prerequisite is unmet). */
  enabled?: boolean;
  /** Convert a thrown value into the message shown to the user. */
  toMessage?: (error: unknown) => string;
}

export function useAsyncData<T>(
  loader: () => Promise<T>,
  deps: unknown[],
  options: UseAsyncDataOptions = {}
): AsyncData<T> {
  const { enabled = true, toMessage } = options;

  const [data, setData] = useState<T | null>(null);
  const [isLoading, setIsLoading] = useState(enabled);
  const [error, setError] = useState<string | null>(null);

  // Guards against a stale response landing after deps changed or unmount.
  const requestId = useRef(0);
  const mounted = useRef(true);
  const loaderRef = useRef(loader);
  loaderRef.current = loader;

  useEffect(() => {
    mounted.current = true;
    return () => {
      mounted.current = false;
    };
  }, []);

  const run = useCallback(async () => {
    if (!enabled) {
      setIsLoading(false);
      return;
    }

    const currentRequest = ++requestId.current;
    setIsLoading(true);
    setError(null);

    try {
      const result = await loaderRef.current();
      if (!mounted.current || currentRequest !== requestId.current) return;
      setData(result);
    } catch (caught) {
      if (!mounted.current || currentRequest !== requestId.current) return;
      const message = toMessage
        ? toMessage(caught)
        : caught instanceof Error && caught.message
          ? caught.message
          : "The request failed.";
      setError(message);
    } finally {
      if (mounted.current && currentRequest === requestId.current) {
        setIsLoading(false);
      }
    }
  }, [enabled, toMessage]);

  useEffect(() => {
    void run();
    // `run` is stable for a given enabled/toMessage pair; `deps` drives reloads.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [...deps, enabled]);

  const reload = useCallback(() => {
    void run();
  }, [run]);

  const updateData = useCallback((updater: T | ((current: T | null) => T | null)) => {
    setData((current) =>
      typeof updater === "function" ? (updater as (c: T | null) => T | null)(current) : updater
    );
  }, []);

  return {
    data,
    isLoading,
    isInitialLoading: isLoading && data === null,
    error,
    reload,
    setData: updateData,
  };
}

"use client";

import { apiFetch, apiJson } from "./apiClient";
import {
  fetchMe,
  getAuthSession,
  saveProfileSession,
  UserDetail,
  UserSession,
} from "@/utils/auth";
import {
  createHR,
  createManager,
  createStudent,
  createTeacher,
  deleteHR,
  deleteManager,
  deleteStudent,
  deleteTeacher,
  fetchHRList,
  fetchManagerList,
  fetchStudentList,
  fetchTeacherList,
  updateHR,
  updateManager,
  updateStudent,
  updateTeacher,
  UserProfileResponse,
} from "./userService";

/**
 * Superuser administration client.
 *
 * Responsibilities:
 *  - Aggregate the four role directories into one searchable People list
 *  - Provision / suspend / deactivate people through the role-specific CRUD APIs
 *  - Read and update the signed-in superuser's own profile
 *
 * Role mapping used across the dashboard:
 *   HR        -> `public.hrs`       (HR Manager)
 *   Manager   -> `public.managers`
 *   Teacher   -> `public.teachers`
 *   Intern    -> `public.students`   (the PMS has no separate intern entity;
 *                                       learners and interns are the same record)
 *
 * Every mutation takes the **profile** id, which is what the list endpoints
 * return in `UserProfileResponse.id` and what the PUT/DELETE routes expect.
 */

// ---------------------------------------------------------------------------
// System health
// ---------------------------------------------------------------------------

export interface SystemTelemetryData {
  status: string;
  database_connected: boolean;
  database_latency_ms: number;
  timestamp: number;
}

export interface SystemTelemetryError {
  message: string;
}

/**
 * Probe `GET /api/v1/health` and measure the round-trip latency.
 *
 * This returns *only* what the backend can actually assert. Identity and
 * workload counts come from `GET /api/v1/superuser/overview` instead of being
 * hard-coded, so nothing on the dashboard can drift from the database.
 */
export async function fetchSystemTelemetry(): Promise<SystemTelemetryData | null> {
  try {
    const startTime = Date.now();
    const res = await apiFetch("/api/v1/health", {
      headers: { Accept: "application/json" },
      cache: "no-store",
    });
    const latency = Date.now() - startTime;
    if (!res.ok) return null;

    // The health route answers with the *shape* the backend actually returns:
    //   { status: "ok", database: { status: "connected", table, record_count } }
    // A failed DB probe raises inside verify_supabase_connection(), so the route
    // 500s and we have already bailed out above - `database.status` is the only
    // "is it really up" signal, not merely the presence of a `database` key.
    const data = await res.json();
    const isDbConnected = data?.status === "ok" && data?.database?.status === "connected";

    return {
      status: isDbConnected ? "Operational" : "Degraded",
      database_connected: isDbConnected,
      database_latency_ms: latency,
      timestamp: Date.now(),
    };
  } catch (err) {
    console.warn("Failed to reach the backend health endpoint:", err);
    return null;
  }
}

// ---------------------------------------------------------------------------
// People directory
// ---------------------------------------------------------------------------

export type DirectoryRole = "HR Manager" | "Manager" | "Teacher" | "Intern";

export interface DirectoryPerson {
  /** Profile-table primary key ΓÇö the id every PUT/DELETE endpoint expects. */
  profileId: string;
  /** Linked public.users id. */
  userId: string;
  name: string;
  email: string;
  role: DirectoryRole;
  department: string | null;
  specialization: string | null;
  enrollmentNo: string | null;
  batchId: string | null;
  isActive: boolean;
  createdAt: string | null;
}

function initialsOf(name: string, email: string): string {
  const source = (name || email || "").trim();
  if (!source) return "??";
  const parts = source.split(/[\s._-]+/).filter(Boolean);
  if (parts.length >= 2) {
    return (parts[0][0] + parts[1][0]).toUpperCase();
  }
  return source.slice(0, 2).toUpperCase();
}

function displayName(item: UserProfileResponse, fallback: string): string {
  return (item.name || item.email?.split("@")[0] || fallback).trim();
}

function toPerson(
  item: UserProfileResponse,
  role: DirectoryRole,
  fallback: string
): DirectoryPerson {
  return {
    profileId: item.id,
    userId: item.user_id,
    name: displayName(item, fallback),
    email: item.email || "",
    role,
    department: item.department ?? null,
    specialization: item.specialization ?? null,
    enrollmentNo: item.enrollment_no ?? null,
    batchId: item.batch_id ?? null,
    isActive: item.is_active !== false,
    createdAt: item.created_at ?? null,
  };
}

/**
 * Load every role directory in parallel and normalize it into one list.
 *
 * A directory that fails to load is reported through `failedRoles` rather than
 * silently dropped, so the People page can warn that a bucket is incomplete
 * instead of showing a confidently empty table.
 */
export async function fetchDirectory(): Promise<{
  people: DirectoryPerson[];
  failedRoles: DirectoryRole[];
}> {
  const buckets: Array<{
    role: DirectoryRole;
    fallback: string;
    load: () => Promise<{ items: UserProfileResponse[] }>;
  }> = [
    { role: "HR Manager", fallback: "HR Officer", load: () => fetchHRList() },
    { role: "Manager", fallback: "Manager", load: () => fetchManagerList() },
    { role: "Teacher", fallback: "Teacher", load: () => fetchTeacherList() },
    { role: "Intern", fallback: "Intern", load: () => fetchStudentList() },
  ];

  const results = await Promise.all(
    buckets.map((bucket) =>
      bucket
        .load()
        .then((response) => ({
          role: bucket.role,
          fallback: bucket.fallback,
          items: response.items || [],
          failed: false,
        }))
        .catch((error) => {
          console.warn(`Failed to load ${bucket.role} directory:`, error);
          return { role: bucket.role, fallback: bucket.fallback, items: [], failed: true };
        })
    )
  );

  const people: DirectoryPerson[] = [];
  const failedRoles: DirectoryRole[] = [];

  for (const result of results) {
    if (result.failed) failedRoles.push(result.role);
    for (const item of result.items) {
      people.push(toPerson(item, result.role, result.fallback));
    }
  }

  return { people, failedRoles };
}

// ---------------------------------------------------------------------------
// Batch picker
// ---------------------------------------------------------------------------

/**
 * One row of `GET /api/v1/batches`, trimmed to what a picker renders.
 *
 * Deliberately not the teacher-scoped `fetchTeacherBatches` from
 * `workflowService`: that only returns the *signed-in teacher's* batches, so it
 * would hide every batch a superuser is entitled to place an intern into.
 */
export interface BatchOption {
  id: string;
  name: string;
  department: string | null;
  status: string | null;
}

/**
 * Load every existing batch, for the Add Person intern dropdown.
 *
 * Ordering is the backend's (alphabetical by name). A failure is raised as an
 * `ApiError` so the caller can offer a retry rather than silently showing an
 * empty dropdown that looks like "there are no batches".
 */
export async function fetchBatchOptions(): Promise<BatchOption[]> {
  const items = await apiJson<BatchOption[]>(
    "/api/v1/batches",
    { cache: "no-store" },
    "Could not load batches"
  );
  return items || [];
}

/**
 * Create a batch from the Add Person form, without pre-assigning a lead.
 *
 * The picker's contract is "make a team and put this person in it", so the
 * caller links the new person through their own profile `batch_id` rather than
 * claiming the batch's `teacher_id` / `manager_id` lead slot.
 */
export async function createBatch(payload: {
  name: string;
  department?: string;
  status?: string;
}): Promise<BatchOption> {
  return apiJson<BatchOption>(
    "/api/v1/batches",
    { method: "POST", body: JSON.stringify(payload) },
    "Could not create the batch"
  );
}

// ---------------------------------------------------------------------------
// Mutations
// ---------------------------------------------------------------------------

export type CreatePersonPayload = {
  name: string;
  email: string;
  role: DirectoryRole;
  department?: string;
  specialization?: string;
  enrollment_no?: string;
  /**
   * Batch to place the person in. Only sent for the `Manager`, `Teacher` and
   * `Intern` roles ΓÇö HR profiles have no batch column.
   */
  batch_id?: string;
};

/** Provision a person, routing to the API that owns their role profile. */
export async function createBackendUser(payload: CreatePersonPayload): Promise<DirectoryPerson> {
  const created = await (async () => {
    switch (payload.role) {
      case "HR Manager":
        return createHR({
          name: payload.name,
          email: payload.email,
          department: payload.department,
          specialization: payload.specialization,
        });
      case "Manager":
        return createManager({
          name: payload.name,
          email: payload.email,
          department: payload.department,
          batch_id: payload.batch_id,
        });
      case "Teacher":
        return createTeacher({
          name: payload.name,
          email: payload.email,
          department: payload.department,
          specialization: payload.specialization,
          batch_id: payload.batch_id,
        });
      case "Intern":
        return createStudent({
          name: payload.name,
          email: payload.email,
          department: payload.department,
          enrollment_no: payload.enrollment_no,
          batch_id: payload.batch_id,
        });
    }
  })();

  return toPerson(created, payload.role, payload.name);
}

/** Activate or suspend a person. The backend treats this as a soft state change. */
export async function setPersonActive(person: DirectoryPerson, isActive: boolean): Promise<void> {
  const { profileId, role } = person;
  switch (role) {
    case "HR Manager":
      await updateHR(profileId, { is_active: isActive });
      return;
    case "Manager":
      await updateManager(profileId, { is_active: isActive });
      return;
    case "Teacher":
      await updateTeacher(profileId, { is_active: isActive });
      return;
    case "Intern":
      await updateStudent(profileId, { is_active: isActive });
      return;
  }
}

/**
 * Deactivate a person's profile.
 *
 * The backend implements DELETE as a soft delete (`users.is_active = false`),
 * so the row and its audit trail are preserved.
 */
export async function deactivateBackendUser(person: DirectoryPerson): Promise<void> {
  const { profileId, role } = person;
  switch (role) {
    case "HR Manager":
      await deleteHR(profileId);
      return;
    case "Manager":
      await deleteManager(profileId);
      return;
    case "Teacher":
      await deleteTeacher(profileId);
      return;
    case "Intern":
      await deleteStudent(profileId);
      return;
  }
}

// ---------------------------------------------------------------------------
// Own profile
// ---------------------------------------------------------------------------

export interface CurrentProfile {
  id: string;
  email: string;
  name: string | null;
  isActive: boolean;
  authProvider: string | null;
  createdAt: string | null;
  lastUpdatedAt: string | null;
  role: { id: string; name: string; description?: string | null };
  roleDescription: string | null;
  profileType: string | null;
  department: string | null;
  specialization: string | null;
  enrollmentNo: string | null;
  scopeType: string | null;
  assignedBatchCount: number;
  assignedStudentCount: number;
  assignedWorkflowCount: number;
  scopeDetails: Record<string, unknown>;
  /** Sign-in timestamp recorded client-side when the session was established. */
  loginAt: string | null;
  mustChangePassword: boolean;
  /** How the current session was authenticated: "password" or "cookie"/"microsoft". */
  sessionType: string;
}

function profileFromSession(session: UserSession): CurrentProfile {
  const user: UserDetail = session.user;
  return {
    id: user.id,
    email: user.email,
    name: user.name ?? null,
    isActive: user.is_active !== false,
    authProvider: user.auth_provider ?? null,
    createdAt: user.created_at ?? null,
    lastUpdatedAt: user.last_updated_at ?? null,
    role: { id: user.role?.id ?? "", name: user.role?.name ?? "Unassigned" },
    roleDescription: user.role?.description ?? null,
    profileType: user.profile?.profile_type ?? null,
    department: user.profile?.department ?? null,
    specialization: user.profile?.specialization ?? null,
    enrollmentNo: user.profile?.enrollment_no ?? null,
    scopeType: user.scope?.scope_type ?? null,
    assignedBatchCount: user.scope?.assigned_batch_ids?.length ?? 0,
    assignedStudentCount: user.scope?.assigned_student_ids?.length ?? 0,
    assignedWorkflowCount: user.scope?.assigned_workflow_ids?.length ?? 0,
    scopeDetails: user.scope?.details ?? {},
    loginAt: session.loginAt ?? null,
    mustChangePassword: Boolean(session.mustChangePassword),
    sessionType: session.token ? "Bearer token" : "HttpOnly session cookie",
  };
}

/**
 * Read the signed-in superuser's profile from the cached session.
 *
 * `ProtectedRoute` already resolved `GET /api/v1/auth/me` and persisted the
 * result, so this is synchronous and needs no extra request. Call
 * `refreshProfileFromServer()` to re-read it.
 */
export function getCurrentProfile(): CurrentProfile | null {
  const session = getAuthSession();
  return session ? profileFromSession(session) : null;
}

/** Re-read `GET /api/v1/auth/me` from the API and persist the refreshed session. */
export async function refreshProfileFromServer(): Promise<CurrentProfile> {
  saveProfileSession((await fetchMe()) as UserDetail);

  const session = getAuthSession();
  if (!session) {
    throw new Error("Session could not be re-established after refreshing the profile.");
  }
  return profileFromSession(session);
}

export interface ProfileUpdateResult {
  id: string;
  name: string | null;
  email: string | null;
  updated_at: string | null;
}

/**
 * Update the signed-in user's display name.
 *
 * Only `name` is self-service: `email` is the login identifier and may be bound
 * to a Microsoft object id, so changing it requires an administrator.
 */
export async function updateOwnProfile(payload: { name: string }): Promise<ProfileUpdateResult> {
  return apiJson<ProfileUpdateResult>(
    "/api/v1/auth/me",
    { method: "PUT", body: JSON.stringify(payload) },
    "Could not save your profile"
  );
}

/** Apply a saved name to the cached session so the header updates immediately. */
export function applyProfileNameToSession(name: string): void {
  const session = getAuthSession();
  if (!session) return;
  saveProfileSession({ ...session.user, name });
}

"use client";

export interface UserRole {
  id: string;
  name: string;
  description?: string | null;
}

export interface UserProfile {
  profile_type: string;
  profile_id?: string | null;
  department?: string | null;
  specialization?: string | null;
  enrollment_no?: string | null;
}

export interface UserScope {
  scope_type: string;
  assigned_batch_ids?: string[];
  assigned_student_ids?: string[];
  assigned_workflow_ids?: string[];
  details?: Record<string, unknown>;
}

export interface UserDetail {
  id: string;
  email: string;
  name?: string | null;
  is_active: boolean;
  must_change_password: boolean;
  /** Sign-in provider bound to this identity: "password" or "microsoft". */
  auth_provider?: string | null;
  created_at?: string | null;
  last_updated_at?: string | null;
  role: UserRole;
  profile?: UserProfile | null;
  scope?: UserScope | null;
}

export interface UserSession {
  token: string;
  tokenType: string;
  expiresIn?: number | null;
  mustChangePassword: boolean;
  user: UserDetail;
  role?: UserRole | null;
  profile?: UserProfile | null;
  scope?: UserScope | null;
  loginAt: string;
}

export interface LoginResponseData {
  access_token: string;
  token_type: string;
  expires_in?: number | null;
  must_change_password: boolean;
  user: {
    id: string;
    email: string;
    name?: string | null;
    role_name: string;
    is_active: boolean;
  };
}

const PROFILE_SESSION_KEY = "dailoqa_pms_profile_session";
const LEGACY_TOKEN_SESSION_KEY = "dailoqa_pms_auth_session";

export const PENDING_ROLE_CODE = "MISSING_ROLE_MAPPING";

export function getApiBaseUrl(): string {
  if (typeof window !== "undefined") {
    return "";
  }
  return process.env.NEXT_PUBLIC_API_BASE_URL || "http://localhost:8000";
}

export function getAuthToken(): string | null {
  const session = getAuthSession();
  return session && session.token ? session.token : null;
}

export function getAuthSession(): UserSession | null {
  if (typeof window === "undefined") return null;
  try {
    const profileRaw = localStorage.getItem(PROFILE_SESSION_KEY);
    if (profileRaw) {
      const parsed = JSON.parse(profileRaw) as UserSession;
      if (parsed && parsed.user) return parsed;
    }
    const legacyRaw = localStorage.getItem(LEGACY_TOKEN_SESSION_KEY);
    if (legacyRaw) {
      const parsed = JSON.parse(legacyRaw) as UserSession;
      if (parsed && parsed.user) return parsed;
    }
    return null;
  } catch {
    return null;
  }
}

export function saveAuthSession(session: UserSession): void {
  if (typeof window !== "undefined") {
    if (session.token) {
      localStorage.setItem(LEGACY_TOKEN_SESSION_KEY, JSON.stringify(session));
      localStorage.setItem(PROFILE_SESSION_KEY, JSON.stringify(session));
      return;
    }
    saveProfileSession(session.user);
  }
}

export function saveProfileSession(user: UserDetail): void {
  if (typeof window === "undefined") return;
  const session: UserSession = {
    token: "",
    tokenType: "cookie",
    expiresIn: null,
    mustChangePassword: user.must_change_password,
    user,
    role: user.role,
    profile: user.profile || null,
    scope: user.scope || null,
    loginAt: new Date().toISOString(),
  };
  localStorage.setItem(PROFILE_SESSION_KEY, JSON.stringify(session));
}

export function clearAuthSession(): void {
  if (typeof window !== "undefined") {
    localStorage.removeItem(PROFILE_SESSION_KEY);
    localStorage.removeItem(LEGACY_TOKEN_SESSION_KEY);
  }
}

export function isUserLoggedIn(): boolean {
  return getAuthSession() !== null;
}

export function startMicrosoftLogin(): void {
  if (typeof window === "undefined") return;
  clearAuthSession();
  window.location.assign("/api/auth/microsoft");
}

export function getLoginErrorMessage(code?: string | null): string {
  switch (code) {
    case "INVALID_STATE":
      return "The sign-in request could not be verified. Please try signing in again.";
    case "OAUTH_CANCELLED":
      return "The Microsoft sign-in was cancelled. No changes were made to your account.";
    case "NOT_ELIGIBLE":
      return "This Microsoft account is not eligible to access the PMS portal. Contact your HR administrator.";
    case "AUTH_SERVICE_UNAVAILABLE":
      return "Microsoft sign-in is temporarily unavailable. Please try again later or use your credentials.";
    case "SESSION_CONFIG_ERROR":
      return "Sign-in is not configured correctly. Please contact your administrator.";
    default:
      return "Unable to sign in with Microsoft. Please try again or use your credentials.";
  }
}

export function getRoleDashboardPath(roleName?: string | null): string {
  if (!roleName) return "/student/dashboard";
  const normalized = roleName.trim().toLowerCase();
  if (normalized.includes("student") || normalized.includes("employee") || normalized.includes("trainee")) {
    return "/student/dashboard";
  }
  if (normalized.includes("teacher") || normalized.includes("mentor") || normalized.includes("instructor")) {
    return "/dashboard/teacher";
  }
  if (normalized.includes("manager")) {
    return "/dashboard/manager";
  }
  if (normalized.includes("hr")) {
    return "/dashboard/hr";
  }
  if (normalized.includes("admin")) {
    return "/dashboard/super-admin";
  }
  return "/student/dashboard";
}

export class AuthError extends Error {
  statusCode: number;
  code?: string;

  constructor(message: string, statusCode = 400, code?: string) {
    super(message);
    this.name = "AuthError";
    this.statusCode = statusCode;
    this.code = code;
  }
}

function extractDetailMessage(data: unknown, fallback: string): { message: string; code?: string } {
  let message = fallback;
  let code: string | undefined;
  const detail = (data as Record<string, unknown>)?.detail;
  if (detail) {
    if (typeof detail === "object" && !Array.isArray(detail)) {
      const obj = detail as { message?: string; code?: string };
      message = obj.message || message;
      code = obj.code || code;
    } else if (typeof detail === "string") {
      message = detail;
    }
  }
  return { message, code };
}

export async function apiLogin(identifier: string, password: string): Promise<LoginResponseData> {
  const baseUrl = getApiBaseUrl();
  const url = `${baseUrl}/api/v1/auth/login`;

  let response: Response;
  try {
    response = await fetch(url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Accept: "application/json",
      },
      body: JSON.stringify({ identifier: identifier.trim(), password }),
      credentials: "same-origin",
    });
  } catch {
    throw new AuthError("Unable to connect to authentication service. Please check your network or server.", 502, "NETWORK_ERROR");
  }

  const data = await response.json().catch(() => ({}));

  if (!response.ok) {
    const { message, code } = extractDetailMessage(data, "Invalid login credentials provided.");
    throw new AuthError(message, response.status, code || "AUTH_ERROR");
  }

  return data as LoginResponseData;
}

export async function fetchMe(): Promise<UserDetail> {
  const baseUrl = getApiBaseUrl();
  const url = `${baseUrl}/api/v1/auth/me`;

  let response: Response;
  try {
    response = await fetch(url, {
      method: "GET",
      headers: { Accept: "application/json" },
      credentials: "same-origin",
    });
  } catch {
    throw new AuthError("Failed to reach server to retrieve profile.", 502, "NETWORK_ERROR");
  }

  const data = await response.json().catch(() => ({}));

  if (!response.ok) {
    const { message, code } = extractDetailMessage(data, "Failed to load user profile.");
    throw new AuthError(message, response.status, code || "PROFILE_ERROR");
  }

  return data as UserDetail;
}

export async function apiGetMe(token?: string | null): Promise<UserDetail> {
  if (!token) {
    return fetchMe();
  }
  const baseUrl = getApiBaseUrl();
  const url = `${baseUrl}/api/v1/auth/me`;

  let response: Response;
  try {
    response = await fetch(url, {
      method: "GET",
      headers: {
        Authorization: `Bearer ${token}`,
        Accept: "application/json",
      },
    });
  } catch {
    throw new AuthError("Failed to reach server to retrieve profile.", 502, "NETWORK_ERROR");
  }

  const data = await response.json().catch(() => ({}));

  if (!response.ok) {
    const { message, code } = extractDetailMessage(data, "Failed to load user profile.");
    throw new AuthError(message, response.status, code || "PROFILE_ERROR");
  }

  return data as UserDetail;
}

export async function apiChangePassword(
  newPassword: string,
  confirmPassword?: string,
  tokenOverride?: string
): Promise<{ success: boolean; message: string; must_change_password: boolean }> {
  const token = tokenOverride || getAuthToken();

  const baseUrl = getApiBaseUrl();
  const url = `${baseUrl}/api/v1/auth/change-password`;

  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    Accept: "application/json",
  };
  if (token) {
    headers.Authorization = `Bearer ${token}`;
  }

  let response: Response;
  try {
    response = await fetch(url, {
      method: "POST",
      headers,
      credentials: "same-origin",
      body: JSON.stringify({
        new_password: newPassword,
        confirm_password: confirmPassword || newPassword,
      }),
    });
  } catch {
    throw new AuthError("Unable to connect to authentication service.", 502, "NETWORK_ERROR");
  }

  const data = await response.json().catch(() => ({}));

  if (!response.ok) {
    let message = "Failed to update password.";
    let code = "PASSWORD_CHANGE_ERROR";
    const detail = (data as Record<string, unknown>)?.detail;
    if (detail) {
      if (Array.isArray(detail) && detail.length > 0) {
        const firstErr = detail[0] as { msg?: string };
        message = firstErr.msg ? firstErr.msg.replace(/^Value error,?\s*/i, "") : message;
        code = "VALIDATION_ERROR";
      } else if (typeof detail === "object") {
        const obj = detail as { message?: string; code?: string };
        message = obj.message || message;
        code = obj.code || code;
      } else if (typeof detail === "string") {
        message = detail;
      }
    }
    if (response.status === 422) {
      if (!message || message === "Failed to update password.") {
        message = "Password must be at least 8 characters long.";
      }
    }
    throw new AuthError(message, response.status, code);
  }

  return data;
}

export async function apiLogout(): Promise<void> {
  const token = getAuthToken();
  const baseUrl = getApiBaseUrl();
  const url = `${baseUrl}/api/v1/auth/logout`;
  try {
    await fetch(url, {
      method: "POST",
      headers: token ? { Authorization: `Bearer ${token}`, Accept: "application/json" } : { Accept: "application/json" },
      credentials: "same-origin",
    });
  } catch {
    // Ignore network errors during logout
  }
  clearAuthSession();
}
